def rotation_offset(a, b):
    n = len(a)
    if len(b) != n:
        return -1
    if n == 0:
        return 0
    for k in range(n):
        match = True
        for i in range(n):
            if a[(i + k) % n] != b[i]:
                match = False
                break
        if match:
            return k
    return -1

