def time_zone_shift(time_str, hour_offset):
    hh = int(time_str[:2])
    mm = int(time_str[3:])
    total = hh * 60 + mm + hour_offset * 60
    days = 0
    while total < 0:
        total += 1440
        days -= 1
    while total >= 1440:
        total -= 1440
        days += 1
    return (days, f"{total // 60:02d}:{total % 60:02d}")

