def is_valid_gray_code_step(a, b):
    if len(a) != len(b) or len(a) == 0:
        return False
    diff = 0
    for i in range(len(a)):
        ca, cb = a[i], b[i]
        if ca not in ('0', '1') or cb not in ('0', '1'):
            return False
        if ca != cb:
            diff += 1
    return diff == 1

